function UIFeelingNaughtyPostcardsDialog:FillSelf()
    local DescribeGroupGo
    local url = checkString(self._data.url)
    --么图片
    if url == "" then
        DescribeGroupGo = self.DescribeGroup2
    else
        local strs = CfUtils.Split(url, "/")
        local md5 = ""
        if strs then
            local md5Strs = CfUtils.Split(strs[#strs], ".")
            if md5Strs then
                md5 = checkString(md5Strs[1])
            end
        end
        self.ImgPhoto.Url = url
        self.ImgPhoto.Md5 = md5
        self.ImgPhoto.SavePath = ""
        self.ImgPhoto:LoadSprite()
        DescribeGroupGo = self.DescribeGroup1
    end
    self:FillContent(DescribeGroupGo)
end

function UIFeelingNaughtyPostcardsDialog:FillContent(go)
    if not go then
        return
    end

    CfUtils.FillText(go.transform:Find("TxtName"), self._curEventVo.title)
    CfUtils.FillText(go.transform:Find("TxtContent"), (self._curEventVo.content))
    CfUtils.FillText(go.transform:Find("Viewport/Content/ItemCell/Text"), (self._curEventVo.content))
    KTool.SetActive(go, true)
end

